#!/usr/bin/env bash\nset -euo pipefail\n\n# Helper function to run a single test case\nrun_test() {\n  local seconds=$1\n  local expected=$2\n  local output\n  output=$(../src/uptime_lyric.sh "$seconds")\n  if [[ "$output" == "$expected" ]]; then\n    echo "PASS for $seconds seconds"\n  else\n    echo "FAIL for $seconds seconds"\n    echo "Expected: $expected"\n    echo "Got:      $output"\n    exit 1\n  fi\n}\n\n# Test cases (mocked uptime via argument)\n# 0 seconds -> 0d 0h 0m – just woke up\nrun_test 0 "Uptime: 0d 0h 0m – just woke up"\n\n# 90 seconds (1 minute) -> 0d 0h 1m – still yawning\nrun_test 90 "Uptime: 0d 0h 1m – still yawning"\n\n# 120 seconds (2 minutes) -> 0d 0h 2m – running like a hamster\nrun_test 120 "Uptime: 0d 0h 2m – running like a hamster"\n\n# 90061 seconds (1d 1h 1m 1s) -> 1d 1h 1m – still yawning\nrun_test 90061 "Uptime: 1d 1h 1m – still yawning"\n\n# All tests passed\necho "All tests passed."
